	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		EngineType
	 */
		public EngineType createEngineType( CreateEngineTypeCommand command ) {

		EngineType entity = new EngineType();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setEngineTypeId( command.getEngineTypeId() );
            entity.setEngineModelCode( command.getEngineModelCode() );
            entity.setMaxThrustKn( command.getMaxThrustKn() );
            entity.setCategory( command.getCategory() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of EngineType {0} ", entity.toString() );

		return entity;
	}

